import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        int T = 1;
        while (T-- > 0) {
            String s = scanner.next();
            if (s.length() == 1) {
                char c = s.charAt(0);
                out.println(c == '0' || c == '_' || c == 'X' ? 1 : 0);
            } else {
                boolean hasX = false;
                for (char c : s.toCharArray()) {
                    if (c == 'X') {
                        hasX = true;
                        break;
                    }
                }
                if (!hasX) {
                    out.println(countWays(s));
                } else {
                    int sum = 0;
                    for (int d = 0; d < 10; d++) {
                        StringBuilder sb = new StringBuilder(s);
                        for (int i = 0; i < s.length(); i++) {
                            if (sb.charAt(i) == 'X') sb.setCharAt(i, (char) ('0' + d));
                        }
                        sum += countWays(sb.toString());
                    }
                    out.println(sum);
                }
            }
        }
        out.close();
    }

    static int countWays(String s) {
        int n = s.length();
        int p = s.charAt(0) != '0' ? 1 : 0;
        for (int i = 0; i < n - 2; i++) {
            if (s.charAt(i) == '_') {
                p *= (i == 0 ? 9 : 10);
            }
        }
        char last = s.charAt(n - 1);
        char secondLast = s.charAt(n - 2);
        int p1;
        if (last == '_' && secondLast == '_') {
            p1 = (n == 2) ? 3 : 4;
        } else if (last == '_') {
            p1 = (secondLast == '0' || secondLast == '5' || secondLast == '2' || secondLast == '7') ? 1 : 0;
        } else if (secondLast == '_') {
            if (last == '0') {
                p1 = (n == 2) ? 1 : 2;
            } else if (last == '5') {
                p1 = 2;
            } else {
                p1 = 0;
            }
        } else {
            int val = Integer.parseInt(s.substring(n - 2));
            p1 = (val % 25 == 0) ? 1 : 0;
        }
        return p * p1;
    }
}
